import * as echarts from '../../src/echarts';
import TooltipHTMLContent from '../../src/component/tooltip/TooltipHTMLContent';

function createChart() {
    const el = document.createElement('div');
    el.style.width = '500px';
    el.style.height = '400px';
    document.body.appendChild(el);
    const chart = echarts.init(el);
    return chart;
}

describe('tooltip HTML content listener unbinding', function () {
    it('should unbind DOM event listeners on dispose', function () {
        const chart = createChart();
        const api = chart.getZr().handler ? (chart as any) : null;
        // Build a TooltipHTMLContent directly against the chart's api.
        const content = new TooltipHTMLContent((chart as any)._api, {});
        const el = content.el;

        expect(typeof el.onmouseenter).toBe('function');
        expect(typeof el.onmousemove).toBe('function');
        expect(typeof el.onmouseleave).toBe('function');
        expect(el.parentNode).not.toBeNull();

        content.dispose();

        expect(el.onmouseenter).toBeNull();
        expect(el.onmousemove).toBeNull();
        expect(el.onmouseleave).toBeNull();
        expect(el.parentNode).toBeNull();

        expect(api).not.toBeNull();
        chart.dispose();
    });

    it('should dispose tooltip content when the chart is disposed', function () {
        const chart = createChart();
        chart.setOption({
            tooltip: { show: true },
            xAxis: { type: 'category', data: ['a', 'b'] },
            yAxis: {},
            series: [{ type: 'line', data: [1, 2] }]
        });

        const tooltipView = (chart as any)._componentsViews
            .concat((chart as any)._views)
            .filter(function (view: any) {
                return view._tooltipContent instanceof TooltipHTMLContent;
            })[0];
        expect(tooltipView).toBeTruthy();

        const el = (tooltipView as any)._tooltipContent.el as HTMLDivElement;
        expect(typeof el.onmouseenter).toBe('function');

        chart.dispose();

        expect(el.onmouseenter).toBeNull();
        expect(el.onmousemove).toBeNull();
        expect(el.onmouseleave).toBeNull();
    });
});

